  void Update(){double wall=Wall;float dt=Time.unscaledDeltaTime;frameTimes.Enqueue(dt*1000);while(frameTimes.Count>300)frameTimes.Dequeue();if(wall>statsAt){statsAt=wall+1;var a=frameTimes.ToArray();Array.Sort(a);fp50=a[(a.Length-1)/2];fp95=a[(int)((a.Length-1)*.95)];fp99=a[(int)((a.Length-1)*.99)];}
   var sw=Stopwatch.StartNew();if(!paused){accumulator+=Mathf.Min(dt,.25f)*speed;int steps=0;while(accumulator>=LineSimulation.TickSeconds&&steps++<40){Clock.Step(wall);accumulator-=(float)LineSimulation.TickSeconds;}}else if(wall>heartbeatAt){Clock.Heartbeat(wall,true);heartbeatAt=wall+.5;}simMs=sw.Elapsed.TotalMilliseconds;
