   if(Input.GetKeyDown(KeyCode.F12))ScreenCapture.CaptureScreenshot(Path.Combine(dataPath,"screen-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ")+".png"));if(quitAfter>0&&wall-started>=quitAfter)Application.Quit();
  }
  IEnumerator Capture(LineVisual line,Bottle bottle){captureRunning=true;line.Sending=true;inflight++;yield return new WaitForEndOfFrame();ThreeBatch payload=null;try{if(visuals.Contains(line)){payload=capture.Capture(line,bottle,true,out cameraMs,out readMs,out encodeMs);captured+=3;line.Captured+=3;}}catch(Exception e){nativeDrops+=3;notice="Acquisition failed: "+e.Message;}captureRunning=false;if(payload!=null){if(Arg("--integration-save","")!="")File.WriteAllText(Path.Combine(dataPath,payload.batch_id+".json"),JsonUtility.ToJson(payload));var start=Wall;using(var r=Post("/batch",JsonUtility.ToJson(payload))){r.timeout=3;yield return r.SendWebRequest();transportMs=(Wall-start)*1000;if(r.result==UnityWebRequest.Result.Success){accepted+=3;line.Accepted+=3;}else{nativeDrops+=3;line.Dropped+=3;notice="Explicitly rejected capture: "+r.downloadHandler.text;}CaptureAudit(payload,line,r.result==UnityWebRequest.Result.Success,transportMs);}}line.Sending=false;inflight--;}
  void CaptureAudit(ThreeBatch b,LineVisual line,bool success,double transport){double waitMs=1000*Math.Max(0,DateTime.Parse(b.capture_utc).ToUniversalTime().Subtract(startUtc).TotalSeconds+started-line.PendingAt);captureTimings.Enqueue(new NativeCaptureTiming{batch_id=b.batch_id,acquisition_wait_ms=waitMs});while(captureTimings.Count>96)captureTimings.Dequeue();string path=Path.Combine(dataPath,"captures.jsonl");if(File.Exists(path)&&new FileInfo(path).Length>=4194304){for(int i=2;i>=1;i--){string src=i==1?path:path+"."+(i-1),dst=path+"."+i;if(File.Exists(src)){if(File.Exists(dst))File.Delete(dst);File.Move(src,dst);}}}File.AppendAllText(path,"{\"line_id\":\""+b.line_id+"\",\"session_id\":\""+b.session_id+"\",\"batch_id\":\""+b.batch_id+"\",\"capture_utc\":\""+b.capture_utc+"\",\"accepted\":"+(success?"true":"false")+",\"acquisition_wait_ms\":"+waitMs.ToString("F6",CultureInfo.InvariantCulture)+",\"transport_ms\":"+transport.ToString("F6",CultureInfo.InvariantCulture)+"}\n");}
