  NativeReport Report(){var report=new NativeReport{width=Screen.width,height=Screen.height,pid=Process.GetCurrentProcess().Id,active_lines=visuals.Count,active_views=inspection?visuals.Count*3:0,captured=captured,accepted=accepted,native_drops=nativeDrops,inflight=inflight,pending_capture=PendingCaptures(),benchmark=benchmark,inspection=inspection,paused=paused,acquisition=acquisition,phase=phase,view=view,selected_line=Selected.State.Id,configured_batches_per_line_s=rate,captured_images_s=captured/Math.Max(.01,Wall-started),frame_p50_ms=fp50,frame_p95_ms=fp95,frame_p99_ms=fp99,fps=frameTimes.Count/Math.Max(.001,SumFrames()/1000),simulation_tick_ms=simMs,visual_update_ms=visualMs,camera_render_ms=cameraMs,readback_ms=readMs,encode_ms=encodeMs,transport_ms=transportMs,wall_seconds=Wall-started,oldest_acquisition_seconds=OldestCapture(),capture_timings=captureTimings.ToArray(),lines=new NativeLineReport[visuals.Count]};for(int i=0;i<visuals.Count;i++){var line=visuals[i];report.lines[i]=new NativeLineReport{line_id=line.State.Id,session_id=line.State.Adapter.Session,product=line.Brewery.Product,state=line.State.Mapping.State("packer",Wall),sim_time=line.State.Sim.Time,produced=line.State.Sim.Produced,packed=line.State.Sim.Packed,buffer=line.State.Sim.BufferCount,bottles=line.State.Sim.ActiveCount,captured_images=line.Captured,accepted_images=line.Accepted,dropped_images=line.Dropped,blocked=line.State.Sim.OutfeedRestricted};}return report;}
