  IEnumerator Poll(){polling=true;string line=Selected.State.Id;using(var r=UnityWebRequest.Get(endpoint+"/state?line_id="+line)){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success){state=JsonUtility.FromJson<MultiState>(r.downloadHandler.text);if((!registered||state.active_lines!=visuals.Count)&&!registering)StartCoroutine(Register(true));if(line==Selected.State.Id&&state.results!=null)foreach(var result in state.results)Load(result);else if(line!=Selected.State.Id){state.results=new ThreeResult[0];state.events=new ThreeResult[0];}if(!string.IsNullOrEmpty(state.stop_reason)&&benchmark)Recover(state.stop_reason);}else{state.status="unavailable";state.actual_device="unavailable";state.results=new ThreeResult[0];state.events=new ThreeResult[0];state.lines=new MultiRate[0];registered=false;state.host_cpu_percent=state.native_cpu_percent=state.service_cpu_percent=state.gpu_busy_percent=state.temperature_c=state.cpu_temperature_c=state.native_rss_mb=state.service_rss_mb=state.available_memory_gb=state.monitor_ms=state.monitor_total_ms=-1;state.assistant_state="unavailable";notice="Inspection service unavailable; simulator remains usable";}}polling=false;}
  void Load(ThreeResult result){if(!textures.ContainsKey(result.frame_id)&&loading.Add(result.frame_id))StartCoroutine(GetCrop(result));}
  IEnumerator GetCrop(ThreeResult result){using(var r=UnityWebRequest.Get(endpoint+result.crop_url)){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success){var image=new Texture2D(2,2);if(image.LoadImage(r.downloadHandler.data)){textures[result.frame_id]=image;textureOrder.Enqueue(result.frame_id);while(textureOrder.Count>48){var id=textureOrder.Dequeue();Destroy(textures[id]);textures.Remove(id);}}else Destroy(image);}}loading.Remove(result.frame_id);}
