  void Tags(Rect r){Panel(r);GUI.Label(new Rect(r.x+18,r.y+12,r.width-36,35),Selected.State.Id+" simulated PLC telemetry — source time, units and quality",title);GUILayout.BeginArea(new Rect(r.x+18,r.y+65,r.width-36,r.height-85));tagsScroll=GUILayout.BeginScrollView(tagsScroll);foreach(var t in Selected.State.Mapping.Frame.tags){string quality=staleTelemetry?"Stale":Selected.State.Mapping.Quality(t,Wall);if(GUILayout.Button(t.name+"    "+(quality=="good"?t.Value:quality)+" "+t.unit+"    sim "+t.source_time.ToString("0.00")+"s • "+quality,button,GUILayout.Height(34)))Close(t.asset);GUILayout.Label(t.origin,small);}GUILayout.EndScrollView();GUILayout.EndArea();}
  void Preview(string station,Rect r){Panel(r,new Color(.96f,.97f,.97f));ThreeResult result=null;if(state.results!=null)foreach(var v in state.results)if(v.station_id==station&&v.line_id==Selected.State.Id&&v.session_id==Selected.State.Adapter.Session)result=v;
   if(result!=null&&textures.ContainsKey(result.frame_id))GUI.DrawTexture(new Rect(r.x+7,r.y+22,86,86),textures[result.frame_id],ScaleMode.ScaleToFit);GUI.Label(new Rect(r.x+102,r.y+7,r.width-110,110),station.ToUpperInvariant()+"\n"+(result==null?"Unable to assess — no current evidence":result.wording+"\n"+(paused||result.historical?"HISTORICAL • ":"")+"bottle "+result.bottle_id+" • age "+result.age_seconds.ToString("0.0")+"s"),small);if(result!=null&&GUI.Button(new Rect(r.x+6,r.y+4,86,22),"Open",button)){review=result;Load(result);view="Failure review";}}
