   if(review!=null){if(textures.ContainsKey(review.frame_id))GUI.DrawTexture(new Rect(700,270,310,310),textures[review.frame_id],ScaleMode.ScaleToFit);GUI.Label(new Rect(1050,260,800,325),review.wording+"\n"+review.line_id+" / bottle "+review.bottle_id+" / "+review.station_id+"\nSession "+review.session_id+"\nFrame "+review.frame_id+"\nCapture "+review.capture_utc+"\n"+review.device+" / "+review.backend+"\nCapture→result "+review.end_to_end_ms.ToString("0.00")+"ms • queue "+review.queue_ms.ToString("0.00")+"ms\n"+review.reason,text);GUI.enabled=!benchmark;if(Button(1050,610,380,"Explain recorded event • optional Qwen"))StartCoroutine(Command("/explain","{\"frame_id\":\""+review.frame_id+"\"}"));GUI.enabled=true;}
