  void DebugPanel(){Panel(new Rect(230,175,1675,845));GUI.Label(new Rect(250,192,1620,38),"Compute activity — actual workload and bounded counters",title);GUI.Label(new Rect(255,260,780,700),"Lines "+visuals.Count+" • configured views "+(inspection?visuals.Count*3:0)+"\nAcquisition "+acquisition+" • target "+rate.ToString("0.00")+" three-view batches/line/s\nCaptured "+captured+" images • "+(captured/Math.Max(.01,Wall-started)).ToString("0.00")+" images/s\nAccepted "+state.accepted+" • completed "+state.completed+"\nCompleted "+state.inspection_rate.ToString("0.00")+" images/s / "+state.bottle_batches_rate.ToString("0.00")+" three-view batches/s\nRates: captured/player lifetime; completed/backend lifetime\nLine-list rate = current registered-session average\nNative drops "+nativeDrops+" • backend drops "+state.dropped+" • cancelled "+state.cancelled+"\nQueue "+state.queue_depth+" • oldest "+state.oldest_request_age_seconds.ToString("0.00")+"s\n2s deadlines missed "+state.missed_deadlines+" • stale "+state.stale+"\nCapture→result p50/p95/p99 "+state.end_to_end_p50_ms.ToString("0.0")+" / "+state.end_to_end_p95_ms.ToString("0.0")+" / "+state.end_to_end_p99_ms.ToString("0.0")+"ms\nTrigger→result p95 "+(state.trigger_timing_samples>0?state.trigger_to_result_p95_ms.ToString("0.0")+"ms":"N/A")+" • samples "+state.trigger_timing_samples+"\nAcquisition pending "+PendingCaptures()+" • oldest "+OldestCapture().ToString("0.00")+"s\nWorst latest line latency "+state.worst_line_latency_ms.ToString("0.0")+"ms\nVision "+state.status+" • selected "+state.selected_device+" / actual "+state.actual_device+"\n"+state.gpu_status+"\nQueue fairness: one batch/line, FIFO admission; camera round robin\nQwen "+state.assistant_state+" (disabled in measurements)",text);GUI.Label(new Rect(1070,260,790,700),"Unity frame p50/p95/p99 (≤300 intervals) "+fp50.ToString("0.00")+" / "+fp95.ToString("0.00")+" / "+fp99.ToString("0.00")+"ms\n60FPS target • VSync0 • 4MSAA\nUnity rendering GPU: "+SystemInfo.graphicsDeviceName+"\nHost CPU "+Metric(state.host_cpu_percent)+"% (all32 logical=100%)\nNative CPU "+Metric(state.native_cpu_percent)+"% (one core=100%)\nBackend CPU "+Metric(state.service_cpu_percent)+"% (one core=100%)\nDevice-wide GPU "+Metric(state.gpu_busy_percent)+"% (amdgpu sysfs, all workloads)\nGPU temp1 "+Metric(state.temperature_c)+"°C • CPU Tctl "+Metric(state.cpu_temperature_c)+"°C\nNative RSS "+Metric(state.native_rss_mb)+"MB / backend RSS "+Metric(state.service_rss_mb)+"MB\nAvailable shared RAM "+Metric(state.available_memory_gb)+"GiB\nMonitor "+Metric(state.monitor_total_ms)+"ms/sample •1Hz\nRSS and shared GPU memory overlap; never summed\nPer-process GPU attribution N/A\nBenchmark phase "+phase+"\nResource guards:16GiB free /85°C GPU /90°C CPU /8s heartbeat\nSim speed1 is separate from camera service cadence",text);}
  void OnApplicationQuit(){File.WriteAllLines(Path.Combine(dataPath,"frames.csv"),frameRows);File.WriteAllText(Path.Combine(dataPath,"run.json"),"{\"started_utc\":\""+startUtc.ToString("o")+"\",\"unity\":\""+Application.unityVersion+"\",\"graphics\":\""+SystemInfo.graphicsDeviceName+"\",\"width\":"+Screen.width+",\"height\":"+Screen.height+",\"frame_cap\":60,\"vsync\":0,\"msaa\":4,\"line_count\":"+visuals.Count+",\"inspection\":"+(inspection?"true":"false")+",\"acquisition\":\""+acquisition+"\",\"wall_seconds\":"+(Wall-started).ToString("F6",CultureInfo.InvariantCulture)+"}");}
  void OnDestroy(){foreach(var v in visuals)v.Dispose();if(capture!=null)capture.Dispose();foreach(var t in textures.Values)Destroy(t);}
